contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount, uint minSum, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(collectAmt <= amount);
        require(minSum <= amount);
        require(collectAmt > 0);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(0)); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        c.Collect(collectAmt); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == balBefore - collectAmt && address(c).balance == ethBefore - collectAmt);
    }
    receive() external payable {}
}

