pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 amount, uint256 minSum, uint256 collectAmt) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(collectAmt <= amount);
        vm.assume(minSum <= amount);
        vm.assume(collectAmt > 0);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(0)) {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        try c.Collect(collectAmt) {} catch { return; }
        assertTrue(c.balances(address(this)) == balBefore - collectAmt && address(c).balance == ethBefore - collectAmt);
    }

    function testFuzz_run(uint256 amount, uint256 minSum, uint256 collectAmt) public {
        _run(amount, minSum, collectAmt);
    }

    receive() external payable {}
}
